const money = (n: number) => `Rs. ${n.toLocaleString('en-PK', { minimumFractionDigits: 0 })}`;
const dateLabel = (value: string) => new Date(value).toLocaleDateString('en-PK', { day: '2-digit', month: 'short', year: 'numeric' });
const dateKey = (value: Date | string) => new Date(value).toISOString().slice(0, 10);
const uid = (prefix: string) => `${prefix}${Date.now().toString(36)}`;
const loadData = (): Data => { try { const saved = localStorage.getItem('hamza-rusk-data'); return saved ? JSON.parse(saved) : seed; } catch { return seed; } };
const queryClient = new QueryClient();

function App() {
  const [data, setData] = useState<Data>(loadData);
  const [toast, setToast] = useState('');
  useEffect(() => { localStorage.setItem('hamza-rusk-data', JSON.stringify(data)); }, [data]);
  const notify = (message: string) => { setToast(message); window.setTimeout(() => setToast(''), 2600); };
  const update = (patch: Partial<Data>, message?: string) => { setData((d) => ({ ...d, ...patch })); if (message) notify(message); };
  const reset = () => { if (window.confirm('Reset all local demo data? This cannot be undone.')) { setData(seed); notify('Demo data restored'); } };
  return <QueryClientProvider client={queryClient}><TooltipProvider><AppRouter data={data} update={update} notify={notify} reset={reset} /><Toaster />{toast && <div className="toast" data-testid="status-toast"><Check size={16} /> {toast}</div>}</TooltipProvider></QueryClientProvider>;
}

function AppRouter({ data, update, notify, reset }: { data: Data; update: (patch: Partial<Data>, message?: string) => void; notify: (message: string) => void; reset: () => void }) {
  const [location] = useLocation();
  return <RoutedErrorBoundary resetKey={location}><Shell data={data}><Switch>
    <Route path="/" component={() => <Dashboard data={data} />} />
    <Route path="/pos" component={() => <POS data={data} update={update} notify={notify} />} />
    <Route path="/products" component={() => <Products data={data} update={update} notify={notify} />} />
    <Route path="/customers" component={() => <Customers data={data} update={update} />} />
    <Route path="/purchases" component={() => <Purchases data={data} update={update} notify={notify} />} />
    <Route path="/inventory" component={() => <Inventory data={data} update={update} notify={notify} />} />
    <Route path="/sales" component={() => <Sales data={data} />} />
    <Route path="/reports" component={() => <Reports data={data} />} />
    <Route path="/settings" component={() => <SettingsPage data={data} update={update} reset={reset} notify={notify} />} />
    <Route component={NotFound} />
  </Switch></Shell></RoutedErrorBoundary>;
}
function RoutedErrorBoundary({ children, resetKey }: { children: ReactNode; resetKey: string }) { return <ErrorBoundary resetKey={resetKey}>{children}</ErrorBoundary>; }

const nav = [
  { href: '/', label: 'Overview', icon: Home },
  { href: '/pos', label: 'Point of sale', icon: ShoppingCart },
  { href: '/sales', label: 'Sales history', icon: Receipt },
  { href: '/customers', label: 'Customers', icon: Users },
  { href: '/products', label: 'Products', icon: Package },
  { href: '/inventory', label: 'Inventory', icon: Boxes },
  { href: '/purchases', label: 'Purchases', icon: ShoppingBag },
  { href: '/reports', label: 'Reports', icon: BarChart3 },
];
function Shell({ children, data }: { children: ReactNode; data: Data }) {
  const [location] = useLocation(); const [menu, setMenu] = useState(false);
  return <div className="app-shell">
    <aside className="sidebar">
      <div style={{ padding: '24px 24px 20px', display: 'flex', alignItems: 'center', gap: 11 }}><img src="/favicon.svg" alt="Hamza Rusk logo" style={{ width: 34, height: 34, borderRadius: 10, display: 'block' }} /><div className="brand-copy"><div style={{ fontFamily: 'var(--app-font-serif)', fontSize: 17 }}>Hamza Rusk</div><div style={{ fontSize: 10, color: 'hsl(var(--sidebar-foreground) / .48)', marginTop: 2 }}>COUNTER DESK</div></div></div>
      <div className="nav-label">Workspace</div>{nav.slice(0, 2).map((item) => <NavItem key={item.href} item={item} location={location} />)}
      <div className="nav-label">Records</div>{nav.slice(2, 7).map((item) => <NavItem key={item.href} item={item} location={location} />)}
      <div className="nav-label">Insights</div><NavItem item={nav[7]} location={location} />
      <div style={{ marginTop: 'auto', paddingBottom: 12 }}><NavItem item={{ href: '/settings', label: 'Settings', icon: SettingsIcon }} location={location} /><div className="sidebar-foot" style={{ padding: '12px 24px 0', borderTop: '1px solid hsl(var(--sidebar-border))', color: 'hsl(var(--sidebar-foreground) / .42)', fontSize: 10 }}>OFFLINE MODE · DATA ON THIS DEVICE</div></div>
    </aside>
    <div className="main-wrap">
      <header className="topbar"><button className="btn btn-ghost" onClick={() => setMenu(!menu)} style={{ padding: 7 }} data-testid="button-menu"><Menu size={18} /></button><div className="topbar-search" style={{ maxWidth: 430, flex: 1, position: 'relative' }}><Search size={15} style={{ position: 'absolute', left: 12, top: 11, color: 'hsl(var(--muted-foreground))' }} /><input className="field" style={{ paddingLeft: 36, background: 'hsl(var(--muted) / .54)' }} placeholder="Search products, customers, records" data-testid="input-global-search" /></div><div style={{ marginLeft: 'auto', display: 'flex', alignItems: 'center', gap: 12 }}><span className="hide-mobile" style={{ fontSize: 12, color: 'hsl(var(--muted-foreground))' }}>Local workspace</span><span style={{ width: 30, height: 30, borderRadius: 50, display: 'grid', placeItems: 'center', background: 'hsl(var(--accent))', color: 'hsl(var(--accent-foreground))', fontWeight: 700, fontSize: 12 }}>HA</span></div></header>
      {menu && <div className="card" style={{ position: 'fixed', top: 60, left: 12, zIndex: 20, padding: 8 }}><b style={{ display: 'block', padding: 8, fontSize: 12 }}>Quick navigation</b>{nav.concat({ href: '/settings', label: 'Settings', icon: SettingsIcon }).map((item) => <NavItem key={item.href} item={item} location={location} onClick={() => setMenu(false)} />)}</div>}
      {children}
    </div>
  </div>;
}
function NavItem({ item, location, onClick }: { item: { href: string; label: string; icon: typeof Home }; location: string; onClick?: () => void }) { const Icon = item.icon; return <Link href={item.href} className={`nav-link ${location === item.href ? 'active' : ''}`} onClick={onClick} data-testid={`link-${item.label.toLowerCase().replaceAll(' ', '-')}`}><Icon size={16} strokeWidth={1.8} /><span>{item.label}</span></Link>; }

function PageHead({ eyebrow, title, description, action }: { eyebrow?: string; title: string; description?: string; action?: ReactNode }) { return <div className="mobile-stack" style={{ display: 'flex', alignItems: 'flex-end', justifyContent: 'space-between', gap: 16, marginBottom: 28 }}><div><div className="mono" style={{ color: 'hsl(var(--primary))', fontSize: 10, letterSpacing: '.12em', textTransform: 'uppercase', marginBottom: 8 }}>{eyebrow || 'Hamza Rusk'}</div><h1 className="serif" style={{ fontSize: 'clamp(28px, 4vw, 42px)', margin: 0, lineHeight: 1.05 }}>{title}</h1>{description && <p style={{ margin: '9px 0 0', color: 'hsl(var(--muted-foreground))', fontSize: 13 }}>{description}</p>}</div>{action}</div>; }
function Stat({ label, value, hint, icon: Icon, accent = false }: { label: string; value: string; hint: string; icon: typeof TrendingUp; accent?: boolean }) { return <div className="card" style={{ padding: 18, background: accent ? 'hsl(var(--primary))' : undefined, color: accent ? 'hsl(var(--primary-foreground))' : undefined }}><div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start' }}><span style={{ fontSize: 12, color: accent ? 'inherit' : 'hsl(var(--muted-foreground))' }}>{label}</span><Icon size={17} style={{ opacity: .72 }} /></div><div className="serif" style={{ fontSize: 28, marginTop: 13 }}>{value}</div><div style={{ fontSize: 11, marginTop: 6, opacity: .72 }}>{hint}</div></div>; }
function Empty({ title, detail, icon: Icon = Archive }: { title: string; detail: string; icon?: typeof Archive }) { return <div style={{ textAlign: 'center', padding: '48px 20px', color: 'hsl(var(--muted-foreground))' }}><Icon size={27} style={{ margin: '0 auto 12px', opacity: .58 }} /><div style={{ color: 'hsl(var(--foreground))', fontWeight: 700, fontSize: 14 }}>{title}</div><div style={{ fontSize: 12, marginTop: 6 }}>{detail}</div></div>; }
function SearchBar({ value, onChange, placeholder = 'Search records...' }: { value: string; onChange: (v: string) => void; placeholder?: string }) { return <div style={{ position: 'relative', flex: 1, maxWidth: 360 }}><Search size={15} style={{ position: 'absolute', left: 12, top: 11, color: 'hsl(var(--muted-foreground))' }} /><input className="field" value={value} onChange={(e) => onChange(e.target.value)} style={{ paddingLeft: 35 }} placeholder={placeholder} data-testid="input-search" /></div>; }
function TableTools({ search, setSearch, exportRows, placeholder }: { search: string; setSearch: (v: string) => void; exportRows: () => void; placeholder?: string }) { return <div className="mobile-stack" style={{ display: 'flex', alignItems: 'center', gap: 10, marginBottom: 14 }}><SearchBar value={search} onChange={setSearch} placeholder={placeholder} /><button className="btn btn-secondary" onClick={exportRows} data-testid="button-export-csv"><ArrowDownToLine size={15} /> Export CSV</button><button className="btn btn-ghost hide-mobile" data-testid="button-filter"><SlidersHorizontal size={16} /></button></div>; }
function exportCSV(filename: string, rows: Record<string, unknown>[]) { if (!rows.length) return; const keys = Object.keys(rows[0]); const csv = [keys.join(','), ...rows.map((row) => keys.map((key) => `"${String(row[key] ?? '').replaceAll('"', '""')}"`).join(','))].join('\\n'); const blob = new Blob([csv], { type: 'text/csv' }); const url = URL.createObjectURL(blob); const a = document.createElement('a'); a.href = url; a.download = filename; a.click(); URL.revokeObjectURL(url); }

function Dashboard({ data }: { data: Data }) {
  const today = data.sales.filter((s) => dateKey(s.createdAt) === dateKey(new Date())); const todayTotal = today.reduce((a, s) => a + s.total, 0); const low = data.products.filter((p) => p.stock <= p.lowStockAt); const units = today.reduce((a, s) => a + s.items.reduce((x, i) => x + i.qty, 0), 0);
  return <main className="page"><PageHead eyebrow={new Date().toLocaleDateString('en-PK', { weekday: 'long', day: '2-digit', month: 'long', year: 'numeric' })} title="Good morning, Hamza." description="A clear view of the counter, the bake room, and what needs your attention." action={<Link href="/pos" className="btn btn-primary" data-testid="link-open-counter"><ShoppingCart size={16} /> Open counter</Link>} />
    <div className="stat-grid" style={{ display: 'grid', gridTemplateColumns: 'repeat(4, 1fr)', gap: 12, marginBottom: 24 }}><Stat label="Today's sales" value={money(todayTotal)} hint={`${today.length} completed tickets`} icon={CircleDollarSign} accent /><Stat label="Items moved" value={String(units)} hint="Across today's tickets" icon={TrendingUp} /><Stat label="Low stock" value={String(low.length).padStart(2, '0')} hint={low.length ? 'Needs a look today' : 'All shelves look good'} icon={AlertTriangle} /><Stat label="Open credit" value={money(data.customers.reduce((a, c) => a + c.balance, 0))} hint="Customer balances" icon={Wallet} /></div>
    <div className="mobile-grid" style={{ display: 'grid', gridTemplateColumns: '1.45fr .9fr', gap: 16 }}>
      <section className="card"><div style={{ padding: '19px 20px', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}><div><h2 style={{ margin: 0, fontSize: 15 }}>Today's rhythm</h2><p style={{ margin: '4px 0 0', color: 'hsl(var(--muted-foreground))', fontSize: 12 }}>Sales across the last six open days</p></div><Link href="/reports" style={{ color: 'hsl(var(--primary))', fontSize: 12, textDecoration: 'none' }}>View report <ChevronRight size={13} style={{ verticalAlign: 'middle' }} /></Link></div><div style={{ padding: '12px 20px 24px', display: 'flex', alignItems: 'end', gap: 12, height: 190, borderTop: '1px solid hsl(var(--border))' }}>{[48, 65, 54, 79, 62, Math.min(100, Math.max(12, (todayTotal / 4500) * 100))].map((height, i) => <div key={i} style={{ flex: 1, textAlign: 'center' }}><div style={{ height: 125, display: 'flex', alignItems: 'end' }}><div style={{ width: '100%', height: `${height}%`, background: i === 5 ? 'hsl(var(--primary))' : 'hsl(var(--secondary))', borderRadius: '6px 6px 2px 2px', transition: 'height .4s' }} /></div><div className="mono" style={{ fontSize: 9, color: 'hsl(var(--muted-foreground))', marginTop: 9 }}>{['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Today'][i]}</div></div>)}</div></section>
      <section className="card"><div style={{ padding: '19px 20px', borderBottom: '1px solid hsl(var(--border))' }}><h2 style={{ margin: 0, fontSize: 15 }}>Needs attention</h2><p style={{ margin: '4px 0 0', color: 'hsl(var(--muted-foreground))', fontSize: 12 }}>Small things worth catching early</p></div>{low.slice(0, 3).map((p) => <Link href="/inventory" key={p.id} style={{ display: 'flex', alignItems: 'center', gap: 11, padding: '14px 20px', borderBottom: '1px solid hsl(var(--border))', textDecoration: 'none', color: 'inherit' }} data-testid={`link-low-stock-${p.id}`}><div style={{ width: 32, height: 32, borderRadius: 8, background: 'hsl(var(--accent))', display: 'grid', placeItems: 'center', color: 'hsl(var(--primary))' }}><Package size={15} /></div><div style={{ flex: 1 }}><div style={{ fontSize: 13, fontWeight: 600 }}>{p.name}</div><div style={{ fontSize: 11, color: 'hsl(var(--muted-foreground))' }}>{p.stock === 0 ? 'Out of stock' : `${p.stock} ${p.unit}s left`}</div></div><AlertTriangle size={15} color="hsl(var(--primary))" /></Link>)}{!low.length && <Empty title="Shelves are in good shape" detail="No low-stock items to review." icon={Check} />}</section>
    </div>
    <section className="card" style={{ marginTop: 16 }}><div style={{ padding: '18px 20px', display: 'flex', justifyContent: 'space-between' }}><h2 style={{ margin: 0, fontSize: 15 }}>Latest tickets</h2><Link href="/sales" style={{ color: 'hsl(var(--primary))', fontSize: 12, textDecoration: 'none' }}>All sales <ChevronRight size={13} style={{ verticalAlign: 'middle' }} /></Link></div><div className="table-wrap"><table><thead><tr><th>Receipt</th><th>Customer</th><th>Items</th><th>Total</th><th>Payment</th><th>Time</th></tr></thead><tbody>{today.slice(0, 4).map((s) => <tr key={s.id}><td className="mono" data-testid={`text-receipt-${s.id}`}>{s.receiptNo}</td><td>{s.customerName}</td><td>{s.items.reduce((a, i) => a + i.qty, 0)} items</td><td style={{ fontWeight: 700 }}>{money(s.total)}</td><td><span className="badge badge-green">{s.paymentMethod}</span></td><td style={{ color: 'hsl(var(--muted-foreground))' }}>{new Date(s.createdAt).toLocaleTimeString('en-PK', { hour: '2-digit', minute: '2-digit' })}</td></tr>)}</tbody></table></div></section>
  </main>;
}

function Modal({ title, description, onClose, children }: { title: string; description?: string; onClose: () => void; children: ReactNode }) { return <div className="modal-backdrop" onMouseDown={(e) => e.target === e.currentTarget && onClose()}><div className="modal" role="dialog" aria-modal="true"><div style={{ padding: '20px 22px 16px', borderBottom: '1px solid hsl(var(--border))', display: 'flex', justifyContent: 'space-between' }}><div><h2 style={{ margin: 0, fontSize: 18 }}>{title}</h2>{description && <p style={{ margin: '5px 0 0', color: 'hsl(var(--muted-foreground))', fontSize: 12 }}>{description}</p>}</div><button className="btn btn-ghost" onClick={onClose} style={{ padding: 5 }} data-testid="button-close-modal"><X size={17} /></button></div>{children}</div></div>; }
function ProductForm({ product, onSave, onClose }: { product?: Product; onSave: (p: Product) => void; onClose: () => void }) {
  const [form, setForm] = useState<Product>(product || { id: uid('p'), name: '', sku: '', category: 'Signature', unit: 'box', price: 0, cost: 0, stock: 0, lowStockAt: 6, active: true }); const set = (key: keyof Product, value: string | number | boolean) => setForm((f) => ({ ...f, [key]: value }));
  return <Modal title={product ? 'Edit product' : 'Add product'} description="Keep the shelf label and stock count in one place." onClose={onClose}><form onSubmit={(e) => { e.preventDefault(); if (!form.name.trim()) return; onSave(form); }} style={{ padding: 22 }}><div style={{ display: 'grid', gap: 15 }}><label><span className="field-label">Product name</span><input autoFocus className="field" value={form.name} onChange={(e) => set('name', e.target.value)} placeholder="e.g. Pista Rusk" data-testid="input-product-name" required /></label><div className="mobile-grid" style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 12 }}><label><span className="field-label">SKU / code</span><input className="field" value={form.sku} onChange={(e) => set('sku', e.target.value)} placeholder="RUSK-024" data-testid="input-product-sku" required /></label><label><span className="field-label">Category</span><select className="field" value={form.category} onChange={(e) => set('category', e.target.value)} data-testid="select-product-category"><option>Signature</option><option>Daily bake</option><option>Flavoured</option><option>Gift boxes</option></select></label></div><div className="mobile-grid" style={{ display: 'grid', gridTemplateColumns: 'repeat(2, 1fr)', gap: 12 }}><label><span className="field-label">Selling price</span><input type="number" min="0" className="field" value={form.price} onChange={(e) => set('price', Number(e.target.value))} data-testid="input-product-price" /></label><label><span className="field-label">Cost price</span><input type="number" min="0" className="field" value={form.cost} onChange={(e) => set('cost', Number(e.target.value))} data-testid="input-product-cost" /></label><label><span className="field-label">Stock on hand</span><input type="number" min="0" className="field" value={form.stock} onChange={(e) => set('stock', Number(e.target.value))} data-testid="input-product-stock" /></label><label><span className="field-label">Low stock at</span><input type="number" min="0" className="field" value={form.lowStockAt} onChange={(e) => set('lowStockAt', Number(e.target.value))} data-testid="input-product-low-stock" /></label></div><label style={{ display: 'flex', alignItems: 'center', gap: 9, fontSize: 13 }}><input type="checkbox" checked={form.active} onChange={(e) => set('active', e.target.checked)} data-testid="input-product-active" /> Available at the counter</label></div><div style={{ display: 'flex', justifyContent: 'flex-end', gap: 8, marginTop: 24 }}><button type="button" className="btn btn-secondary" onClick={onClose} data-testid="button-cancel-product">Cancel</button><button className="btn btn-primary" data-testid="button-save-product"><Check size={15} /> Save product</button></div></form></Modal>;
}
function Products({ data, update, notify }: { data: Data; update: (patch: Partial<Data>, message?: string) => void; notify: (message: string) => void }) {
  const [search, setSearch] = useState(''); const [editing, setEditing] = useState<Product | null | undefined>(undefined); const [category, setCategory] = useState('All');
  const rows = useMemo(() => data.products.filter((p) => (category === 'All' || p.category === category) && `${p.name} ${p.sku}`.toLowerCase().includes(search.toLowerCase())), [data.products, search, category]);
  const save = (product: Product) => { update({ products: data.products.some((p) => p.id === product.id) ? data.products.map((p) => p.id === product.id ? product : p) : [...data.products, product] }, product.id && data.products.some((p) => p.id === product.id) ? 'Product updated' : 'Product added'); setEditing(undefined); };
  const remove = (id: string) => { const p = data.products.find((x) => x.id === id); if (p && window.confirm(`Delete ${p.name}?`)) update({ products: data.products.filter((x) => x.id !== id) }, 'Product deleted'); };
  return <main className="page"><PageHead eyebrow="Catalog" title="Products" description="Your bake list, shelf counts, and prices — kept tidy." action={<button className="btn btn-primary" onClick={() => setEditing(null)} data-testid="button-add-product"><Plus size={16} /> Add product</button>} /><div className="stat-grid" style={{ display: 'grid', gridTemplateColumns: 'repeat(4, 1fr)', gap: 10, marginBottom: 18 }}><Stat label="All products" value={String(data.products.length)} hint="In your catalog" icon={Package} /><Stat label="Active" value={String(data.products.filter((p) => p.active).length)} hint="Available at counter" icon={Check} /><Stat label="Low stock" value={String(data.products.filter((p) => p.stock <= p.lowStockAt && p.stock > 0).length)} hint="Below threshold" icon={AlertTriangle} /><Stat label="Out of stock" value={String(data.products.filter((p) => p.stock === 0).length)} hint="Needs replenishing" icon={Archive} /></div><section className="card" style={{ padding: 18 }}><div className="mobile-stack" style={{ display: 'flex', alignItems: 'center', gap: 10, marginBottom: 14 }}><SearchBar value={search} onChange={setSearch} placeholder="Search name or SKU..." /><select className="field" style={{ width: 150 }} value={category} onChange={(e) => setCategory(e.target.value)} data-testid="select-product-filter"><option>All</option>{['Signature', 'Daily bake', 'Flavoured', 'Gift boxes'].map((x) => <option key={x}>{x}</option>)}</select><button className="btn btn-secondary" onClick={() => exportCSV('hamza-rusk-products.csv', rows.map(({ name, sku, category: cat, unit, price, cost, stock, active }) => ({ name, sku, category: cat, unit, price, cost, stock, active })))} data-testid="button-export-products"><ArrowDownToLine size={15} /> Export</button></div><div className="table-wrap"><table><thead><tr><th>Product</th><th>Category</th><th>Unit</th><th>Price</th><th>Cost</th><th>Stock on hand</th><th>Status</th><th>Actions</th></tr></thead><tbody>{rows.map((p) => <tr key={p.id}><td><div style={{ fontWeight: 700 }}>{p.name}</div><div className="mono" style={{ fontSize: 10, color: 'hsl(var(--muted-foreground))' }}>{p.sku}</div></td><td>{p.category}</td><td>{p.unit}</td><td style={{ fontWeight: 700 }}>{money(p.price)}</td><td>{money(p.cost)}</td><td>{p.stock}</td><td><span className={`badge ${p.stock === 0 ? 'badge-red' : p.stock <= p.lowStockAt ? 'badge-orange' : 'badge-green'}`}>{p.stock === 0 ? 'Out of stock' : p.stock <= p.lowStockAt ? 'Low stock' : 'Healthy'}</span></td><td><button className="btn btn-ghost" onClick={() => setEditing(p)} data-testid={`button-edit-product-${p.id}`}><Pencil size={14} /></button><button className="btn btn-ghost" onClick={() => remove(p.id)} data-testid={`button-delete-product-${p.id}`}><Trash2 size={14} /></button></td></tr>)}</tbody></table>{!rows.length && <Empty title="No products found" detail="Try a different search or add your first shelf item." icon={Package} />}</div></section>{editing !== undefined && <ProductForm product={editing || undefined} onSave={save} onClose={() => setEditing(undefined)} />}</main>;
}

function CustomerForm({ customer, onSave, onClose }: { customer?: Customer; onSave: (c: Customer) => void; onClose: () => void }) {
  const [form, setForm] = useState<Customer>(customer || { id: uid('c'), name: '', phone: '', email: '', area: '', balance: 0, status: 'Active' }); const set = (key: keyof Customer, value: string | number) => setForm((f) => ({ ...f, [key]: value }));
  return <Modal title={customer ? 'Edit customer' : 'Add customer'} description="A quick record helps the next visit feel familiar." onClose={onClose}><form onSubmit={(e) => { e.preventDefault(); if (form.name && form.phone) onSave(form); }} style={{ padding: 22 }}><div style={{ display: 'grid', gap: 15 }}><label><span className="field-label">Customer name</span><input autoFocus className="field" value={form.name} onChange={(e) => set('name', e.target.value)} placeholder="e.g. Farah Iqbal" required data-testid="input-customer-name" /></label><div className="mobile-grid" style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 12 }}><label><span className="field-label">Phone number</span><input className="field" value={form.phone} onChange={(e) => set('phone', e.target.value)} placeholder="03xx xxx xxxx" required data-testid="input-customer-phone" /></label><label><span className="field-label">Area</span><input className="field" value={form.area} onChange={(e) => set('area', e.target.value)} placeholder="Gulberg III" data-testid="input-customer-area" /></label></div><label><span className="field-label">Email <span style={{ fontWeight: 400, color: 'hsl(var(--muted-foreground))' }}>optional</span></span><input type="email" className="field" value={form.email} onChange={(e) => set('email', e.target.value)} placeholder="name@email.com" data-testid="input-customer-email" /></label><label><span className="field-label">Opening balance</span><input type="number" className="field" value={form.balance} onChange={(e) => set('balance', Number(e.target.value))} data-testid="input-customer-balance" /></label></div><div style={{ display: 'flex', justifyContent: 'flex-end', gap: 8, marginTop: 24 }}><button type="button" className="btn btn-secondary" onClick={onClose}>Cancel</button><button className="btn btn-primary" data-testid="button-save-customer"><Check size={15} /> Save customer</button></div></form></Modal>;
}
function Customers({ data, update }: { data: Data; update: (patch: Partial<Data>, message?: string) => void }) {
  const [search, setSearch] = useState(''); const [editing, setEditing] = useState<Customer | null | undefined>(undefined); const rows = data.customers.filter((c) => `${c.name} ${c.phone} ${c.area}`.toLowerCase().includes(search.toLowerCase()));
  const save = (customer: Customer) => { update({ customers: data.customers.some((c) => c.id === customer.id) ? data.customers.map((c) => c.id === customer.id ? customer : c) : [...data.customers, customer] }, 'Customer saved'); setEditing(undefined); }; const remove = (id: string) => { if (window.confirm('Delete this customer record?')) update({ customers: data.customers.filter((c) => c.id !== id) }, 'Customer deleted'); };
  return <main className="page"><PageHead eyebrow="Relationships" title="Customers" description="Remember regulars, keep credit clear, and make every handover quicker." action={<button className="btn btn-primary" onClick={() => setEditing(null)} data-testid="button-add-customer"><Plus size={16} /> Add customer</button>} /><section className="card" style={{ padding: 18 }}><TableTools search={search} setSearch={setSearch} exportRows={() => exportCSV('hamza-rusk-customers.csv', rows.map(({ name, phone, email, area, balance, status }) => ({ name, phone, email, area, balance, status })))} placeholder="Search name, phone or area..." /><div className="table-wrap"><table><thead><tr><th>Customer</th><th>Contact</th><th>Area</th><th>Balance</th><th>Status</th><th>Actions</th></tr></thead><tbody>{rows.map((c) => <tr key={c.id}><td><div style={{ fontWeight: 700 }}>{c.name}</div><div className="mono" style={{ fontSize: 10, color: 'hsl(var(--muted-foreground))' }}>{c.id.toUpperCase()}</div></td><td>{c.phone}<div style={{ color: 'hsl(var(--muted-foreground))', fontSize: 11 }}>{c.email}</div></td><td>{c.area || '—'}</td><td style={{ fontWeight: c.balance ? 700 : 400, color: c.balance ? 'hsl(var(--primary))' : undefined }}>{c.balance ? money(c.balance) : 'Clear'}</td><td><span className="badge badge-green">{c.status}</span></td><td><button className="btn btn-ghost" onClick={() => setEditing(c)} data-testid={`button-edit-customer-${c.id}`}><Pencil size={14} /></button><button className="btn btn-ghost" onClick={() => remove(c.id)} data-testid={`button-delete-customer-${c.id}`}><Trash2 size={14} /></button></td></tr>)}</tbody></table>{!rows.length && <Empty title="No customers match that search" detail="Try their phone, area, or add a new regular." icon={Users} />}</div></section>{editing !== undefined && <CustomerForm customer={editing || undefined} onSave={save} onClose={() => setEditing(undefined)} />}</main>;
}

function POS({ data, update, notify }: { data: Data; update: (patch: Partial<Data>, message?: string) => void; notify: (message: string) => void }) {
  const [cart, setCart] = useState<SaleItem[]>([]); const [search, setSearch] = useState(''); const [payment, setPayment] = useState('Cash'); const [customer, setCustomer] = useState('Walk-in customer'); const [held, setHeld] = useState<SaleItem[][]>([]);
  const products = data.products.filter((p) => p.active && `${p.name} ${p.sku}`.toLowerCase().includes(search.toLowerCase())); const total = cart.reduce((a, i) => a + i.price * i.qty, 0);
  const add = (p: Product) => setCart((items) => items.some((i) => i.productId === p.id) ? items.map((i) => i.productId === p.id ? { ...i, qty: Math.min(i.qty + 1, p.stock) } : i) : [...items, { productId: p.id, name: p.name, qty: 1, price: p.price }]); const change = (id: string, qty: number) => setCart((items) => qty <= 0 ? items.filter((i) => i.productId !== id) : items.map((i) => i.productId === id ? { ...i, qty } : i));
  const complete = () => {
    if (!cart.length) return notify('Add at least one item first');
    const insufficient = cart.find((item) => (data.products.find((p) => p.id === item.productId)?.stock || 0) < item.qty);
    if (insufficient) return notify(`${insufficient.name} does not have enough stock`);
    const sale: Sale = { id: uid('s'), receiptNo: `HR-${1050 + data.sales.length}`, customerName: customer, items: cart, total, paymentMethod: payment, status: 'Completed', createdAt: new Date().toISOString() };
    const products = data.products.map((p) => { const item = cart.find((i) => i.productId === p.id); return item ? { ...p, stock: p.stock - item.qty } : p; });
    const customers = payment === 'Credit' && customer !== 'Walk-in customer'
      ? data.customers.map((c) => c.name === customer ? { ...c, balance: c.balance + total } : c)
      : data.customers;
    update({ sales: [sale, ...data.sales], products, customers }, `Sale ${sale.receiptNo} completed`); setCart([]); setCustomer('Walk-in customer');
  };
  return <main className="page"><PageHead eyebrow="Counter desk" title="Point of sale" description="Tap a bake, count the bag, and keep the queue moving." action={<span className="badge badge-green"><span style={{ width: 6, height: 6, borderRadius: 6, background: 'currentColor', marginRight: 6 }} /> Offline ready</span>} /><div className="mobile-grid" style={{ display: 'grid', gridTemplateColumns: '1.25fr .75fr', gap: 16, alignItems: 'start' }}><section className="card" style={{ padding: 18 }}><div className="mobile-stack" style={{ display: 'flex', gap: 10, marginBottom: 16 }}><SearchBar value={search} onChange={setSearch} placeholder="Search or scan a product..." /><button className="btn btn-secondary hide-mobile" data-testid="button-pos-shortcut">F2 Search</button></div><div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(160px, 1fr))', gap: 10 }}>{products.map((p) => <button key={p.id} className="card" onClick={() => add(p)} disabled={p.stock === 0} style={{ textAlign: 'left', padding: 14, color: 'inherit', opacity: p.stock === 0 ? .48 : 1, border: '1px solid hsl(var(--border))' }} data-testid={`button-add-to-cart-${p.id}`}><div style={{ height: 62, borderRadius: 9, marginBottom: 12, display: 'grid', placeItems: 'center', background: 'hsl(var(--accent))', color: 'hsl(var(--primary))' }}><ShoppingBag size={25} strokeWidth={1.5} /></div><div style={{ fontWeight: 700, fontSize: 13 }}>{p.name}</div><div style={{ display: 'flex', justifyContent: 'space-between', marginTop: 9, fontSize: 12 }}><span style={{ color: 'hsl(var(--primary))', fontWeight: 700 }}>{money(p.price)}</span><span style={{ color: 'hsl(var(--muted-foreground))' }}>{p.stock} left</span></div></button>)}</div></section><section className="card" style={{ position: 'sticky', top: 84, overflow: 'hidden' }}><div style={{ padding: '18px 18px 14px', borderBottom: '1px solid hsl(var(--border))', display: 'flex', justifyContent: 'space-between' }}><div><h2 style={{ fontSize: 15, margin: 0 }}>Current ticket</h2><div className="mono" style={{ fontSize: 10, color: 'hsl(var(--muted-foreground))', marginTop: 4 }}>DRAFT · NOT SAVED</div></div><button className="btn btn-ghost" onClick={() => setCart([])} data-testid="button-clear-cart"><X size={15} /> Clear</button></div><div style={{ padding: 18, minHeight: 210 }}>{!cart.length ? <Empty title="Ready for the next order" detail="Select a product on the left to begin." icon={Receipt} /> : cart.map((item) => <div key={item.productId} style={{ display: 'flex', gap: 8, alignItems: 'center', marginBottom: 15 }}><div style={{ flex: 1, fontSize: 12, fontWeight: 700 }}>{item.name}<div style={{ fontWeight: 400, color: 'hsl(var(--muted-foreground))', marginTop: 3 }}>{money(item.price)} each</div></div><div style={{ display: 'flex', alignItems: 'center', border: '1px solid hsl(var(--border))', borderRadius: 7 }}><button className="btn btn-ghost" style={{ padding: '4px 7px' }} onClick={() => change(item.productId, item.qty - 1)} data-testid={`button-decrease-${item.productId}`}>−</button><span className="mono" style={{ fontSize: 11 }}>{item.qty}</span><button className="btn btn-ghost" style={{ padding: '4px 7px' }} onClick={() => change(item.productId, item.qty + 1)} data-testid={`button-increase-${item.productId}`}>+</button></div><strong style={{ fontSize: 12, width: 62, textAlign: 'right' }}>{money(item.price * item.qty)}</strong></div>)}</div><div style={{ borderTop: '1px solid hsl(var(--border))', padding: 18 }}><label><span className="field-label">Customer</span><select className="field" value={customer} onChange={(e) => setCustomer(e.target.value)} data-testid="select-pos-customer"><option>Walk-in customer</option>{data.customers.map((c) => <option key={c.id}>{c.name}</option>)}</select></label><div style={{ display: 'flex', gap: 7, marginTop: 10 }}>{['Cash', 'Card', 'Credit'].map((method) => <button key={method} onClick={() => setPayment(method)} className={`btn ${payment === method ? 'btn-primary' : 'btn-secondary'}`} style={{ flex: 1, padding: 8 }} data-testid={`button-payment-${method.toLowerCase()}`}>{method}</button>)}</div><div style={{ display: 'flex', justifyContent: 'space-between', margin: '18px 0 14px', alignItems: 'baseline' }}><span style={{ color: 'hsl(var(--muted-foreground))', fontSize: 12 }}>Total</span><strong className="serif" style={{ fontSize: 27 }}>{money(total)}</strong></div><button className="btn btn-primary" style={{ width: '100%', padding: 12 }} onClick={complete} disabled={!cart.length} data-testid="button-complete-sale"><Check size={16} /> Complete sale</button><button className="btn btn-secondary" style={{ width: '100%', marginTop: 8 }} onClick={() => { if (cart.length) { setHeld([...held, cart]); setCart([]); notify('Ticket held for later'); } }} disabled={!cart.length} data-testid="button-hold-cart"><Archive size={15} /> Hold ticket {held.length ? `(${held.length})` : ''}</button></div></section></div></main>;
}

function Sales({ data }: { data: Data }) { const [search, setSearch] = useState(''); const rows = data.sales.filter((s) => `${s.receiptNo} ${s.customerName} ${s.paymentMethod}`.toLowerCase().includes(search.toLowerCase())); return <main className="page"><PageHead eyebrow="Records" title="Sales history" description="Every ticket, payment method, and rupee — in one dependable ledger." /><section className="card" style={{ padding: 18 }}><TableTools search={search} setSearch={setSearch} exportRows={() => exportCSV('hamza-rusk-sales.csv', rows.map((s) => ({ receipt: s.receiptNo, customer: s.customerName, total: s.total, payment: s.paymentMethod, status: s.status, date: dateLabel(s.createdAt) })))} placeholder="Search receipt or customer..." /><div className="table-wrap"><table><thead><tr><th>Receipt</th><th>Customer</th><th>Items</th><th>Total</th><th>Payment</th><th>Status</th><th>Date</th></tr></thead><tbody>{rows.map((s) => <tr key={s.id}><td className="mono">{s.receiptNo}</td><td style={{ fontWeight: 600 }}>{s.customerName}</td><td>{s.items.reduce((a, i) => a + i.qty, 0)}</td><td style={{ fontWeight: 700 }}>{money(s.total)}</td><td>{s.paymentMethod}</td><td><span className="badge badge-green">{s.status}</span></td><td>{dateLabel(s.createdAt)}</td></tr>)}</tbody></table>{!rows.length && <Empty title="No sales yet" detail="Completed counter tickets will appear here." icon={Receipt} />}</div></section></main>; }

function Purchases({ data, update, notify }: { data: Data; update: (patch: Partial<Data>, message?: string) => void; notify: (message: string) => void }) {
  const [search, setSearch] = useState(''); const [open, setOpen] = useState(false); const [supplier, setSupplier] = useState(''); const [referenceNo, setReference] = useState(''); const [productId, setProduct] = useState(data.products[0]?.id || ''); const [qty, setQty] = useState(1); const rows = data.purchases.filter((p) => `${p.supplier} ${p.referenceNo}`.toLowerCase().includes(search.toLowerCase()));
  const record = (e: React.FormEvent) => { e.preventDefault(); const p = data.products.find((x) => x.id === productId); if (!p || !supplier) return; const purchase: Purchase = { id: uid('b'), supplier, referenceNo: referenceNo || `PO-${data.purchases.length + 2900}`, items: [{ productId: p.id, name: p.name, qty, price: p.cost }], total: qty * p.cost, status: 'Received', createdAt: new Date().toISOString() }; update({ purchases: [purchase, ...data.purchases], products: data.products.map((x) => x.id === p.id ? { ...x, stock: x.stock + qty } : x) }, 'Purchase received and stock updated'); setOpen(false); setSupplier(''); setReference(''); setQty(1); };
  return <main className="page"><PageHead eyebrow="Supply room" title="Purchases" description="Record what came in so your stock and margins stay honest." action={<button className="btn btn-primary" onClick={() => setOpen(true)} data-testid="button-add-purchase"><Plus size={16} /> Record purchase</button>} /><section className="card" style={{ padding: 18 }}><TableTools search={search} setSearch={setSearch} exportRows={() => exportCSV('hamza-rusk-purchases.csv', rows.map((p) => ({ supplier: p.supplier, reference: p.referenceNo, total: p.total, status: p.status, date: dateLabel(p.createdAt) })))} placeholder="Search supplier or reference..." /><div className="table-wrap"><table><thead><tr><th>Reference</th><th>Supplier</th><th>Items</th><th>Total</th><th>Status</th><th>Received</th></tr></thead><tbody>{rows.map((p) => <tr key={p.id}><td className="mono">{p.referenceNo}</td><td style={{ fontWeight: 700 }}>{p.supplier}</td><td>{p.items.map((i) => `${i.name} × ${i.qty}`).join(', ')}</td><td style={{ fontWeight: 700 }}>{money(p.total)}</td><td><span className="badge badge-green">{p.status}</span></td><td>{dateLabel(p.createdAt)}</td></tr>)}</tbody></table>{!rows.length && <Empty title="No purchases recorded" detail="Add an invoice when a delivery lands." icon={ShoppingBag} />}</div></section>{open && <Modal title="Record a purchase" description="Received stock is added to the shelf count immediately." onClose={() => setOpen(false)}><form onSubmit={record} style={{ padding: 22, display: 'grid', gap: 15 }}><label><span className="field-label">Supplier</span><input autoFocus className="field" value={supplier} onChange={(e) => setSupplier(e.target.value)} placeholder="e.g. Lahore Baking Supplies" required data-testid="input-purchase-supplier" /></label><label><span className="field-label">Invoice / reference number</span><input className="field" value={referenceNo} onChange={(e) => setReference(e.target.value)} placeholder="INV-904" data-testid="input-purchase-reference" /></label><div className="mobile-grid" style={{ display: 'grid', gridTemplateColumns: '1fr 120px', gap: 12 }}><label><span className="field-label">Product received</span><select className="field" value={productId} onChange={(e) => setProduct(e.target.value)} data-testid="select-purchase-product">{data.products.map((p) => <option key={p.id} value={p.id}>{p.name}</option>)}</select></label><label><span className="field-label">Quantity</span><input type="number" min="1" className="field" value={qty} onChange={(e) => setQty(Number(e.target.value))} data-testid="input-purchase-quantity" /></label></div><div style={{ display: 'flex', justifyContent: 'flex-end', gap: 8, marginTop: 8 }}><button type="button" className="btn btn-secondary" onClick={() => setOpen(false)}>Cancel</button><button className="btn btn-primary" data-testid="button-save-purchase"><Check size={15} /> Save purchase</button></div></form></Modal>}</main>;
}

function Inventory({ data, update, notify }: { data: Data; update: (patch: Partial<Data>, message?: string) => void; notify: (message: string) => void }) { const [open, setOpen] = useState<Product | null>(null); const [change, setChange] = useState(0); const [reason, setReason] = useState(''); const [search, setSearch] = useState(''); const rows = data.products.filter((p) => `${p.name} ${p.sku}`.toLowerCase().includes(search.toLowerCase())); const save = (e: React.FormEvent) => { e.preventDefault(); if (!open || !change) return; const adjustment: Adjustment = { id: uid('a'), productName: open.name, change, reason: reason || 'Manual count', createdAt: new Date().toISOString() }; update({ products: data.products.map((p) => p.id === open.id ? { ...p, stock: Math.max(0, p.stock + change) } : p), adjustments: [adjustment, ...data.adjustments] }, 'Stock adjusted'); setOpen(null); setChange(0); setReason(''); };
  return <main className="page"><PageHead eyebrow="Stock room" title="Inventory" description="See what is on the shelf, then correct it without losing the trail." /><section className="card" style={{ padding: 18 }}><div className="mobile-stack" style={{ display: 'flex', gap: 10, marginBottom: 14 }}><SearchBar value={search} onChange={setSearch} placeholder="Search stock..." /><span className="badge badge-orange" style={{ padding: '8px 10px' }}>{data.products.filter((p) => p.stock <= p.lowStockAt).length} low stock</span></div><div className="table-wrap"><table><thead><tr><th>Product</th><th>SKU</th><th>On hand</th><th>Threshold</th><th>Stock value</th><th>State</th><th>Action</th></tr></thead><tbody>{rows.map((p) => <tr key={p.id}><td style={{ fontWeight: 700 }}>{p.name}</td><td className="mono">{p.sku}</td><td className="serif" style={{ fontSize: 20 }}>{p.stock}</td><td>{p.lowStockAt}</td><td>{money(p.stock * p.cost)}</td><td><span className={`badge ${p.stock === 0 ? 'badge-red' : p.stock <= p.lowStockAt ? 'badge-orange' : 'badge-green'}`}>{p.stock === 0 ? 'Out' : p.stock <= p.lowStockAt ? 'Low' : 'Healthy'}</span></td><td><button className="btn btn-secondary" onClick={() => setOpen(p)} data-testid={`button-adjust-stock-${p.id}`}><SlidersHorizontal size={14} /> Adjust</button></td></tr>)}</tbody></table></div></section><section className="card" style={{ marginTop: 16, padding: 18 }}><h2 style={{ fontSize: 15, margin: '0 0 14px' }}>Recent adjustments</h2>{data.adjustments.slice(0, 5).map((a) => <div key={a.id} style={{ display: 'flex', gap: 12, borderTop: '1px solid hsl(var(--border))', padding: '12px 0', fontSize: 12 }}><span className={`badge ${a.change < 0 ? 'badge-red' : 'badge-green'}`}>{a.change > 0 ? '+' : ''}{a.change}</span><div style={{ flex: 1 }}><b>{a.productName}</b><div style={{ color: 'hsl(var(--muted-foreground))', marginTop: 3 }}>{a.reason}</div></div><span style={{ color: 'hsl(var(--muted-foreground))' }}>{dateLabel(a.createdAt)}</span></div>)}</section>{open && <Modal title="Adjust stock" description={`Current count: ${open.stock} ${open.unit}s`} onClose={() => setOpen(null)}><form onSubmit={save} style={{ padding: 22, display: 'grid', gap: 15 }}><label><span className="field-label">Change quantity</span><input autoFocus type="number" className="field" value={change} onChange={(e) => setChange(Number(e.target.value))} placeholder="Use a negative number to remove" data-testid="input-stock-change" required /></label><label><span className="field-label">Reason</span><select className="field" value={reason} onChange={(e) => setReason(e.target.value)} data-testid="select-stock-reason"><option value="">Manual count</option><option>Damaged in transit</option><option>Wastage</option><option>Found during count</option><option>Opening balance</option></select></label><div style={{ display: 'flex', justifyContent: 'flex-end', gap: 8 }}><button type="button" className="btn btn-secondary" onClick={() => setOpen(null)}>Cancel</button><button className="btn btn-primary" data-testid="button-save-adjustment"><Check size={15} /> Save adjustment</button></div></form></Modal>}</main>; }

function Reports({ data }: { data: Data }) { const revenue = data.sales.reduce((a, s) => a + s.total, 0); const cost = data.sales.reduce((a, s) => a + s.items.reduce((x, i) => x + (data.products.find((p) => p.id === i.productId)?.cost || 0) * i.qty, 0), 0); const top = [...data.products].sort((a, b) => data.sales.reduce((x, s) => x + s.items.filter((i) => i.productId === b.id).reduce((z, i) => z + i.qty, 0), 0) - data.sales.reduce((x, s) => x + s.items.filter((i) => i.productId === a.id).reduce((z, i) => z + i.qty, 0), 0)).slice(0, 4); return <main className="page"><PageHead eyebrow="Business view" title="Reports" description="A grounded read on what the counter has been doing." action={<button className="btn btn-secondary" onClick={() => exportCSV('hamza-rusk-report.csv', [{ revenue, cost, grossProfit: revenue - cost, tickets: data.sales.length }])} data-testid="button-export-report"><ArrowDownToLine size={15} /> Export summary</button>} /><div className="stat-grid" style={{ display: 'grid', gridTemplateColumns: 'repeat(4, 1fr)', gap: 12, marginBottom: 18 }}><Stat label="Recorded revenue" value={money(revenue)} hint="All completed sales" icon={CircleDollarSign} accent /><Stat label="Gross profit" value={money(revenue - cost)} hint="Before shop expenses" icon={TrendingUp} /><Stat label="Average ticket" value={money(data.sales.length ? revenue / data.sales.length : 0)} hint={`${data.sales.length} tickets`} icon={Receipt} /><Stat label="Stock value" value={money(data.products.reduce((a, p) => a + p.stock * p.cost, 0))} hint="At cost price" icon={Boxes} /></div><div className="mobile-grid" style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 16 }}><section className="card" style={{ padding: 20 }}><h2 style={{ margin: 0, fontSize: 15 }}>Product movement</h2><p style={{ color: 'hsl(var(--muted-foreground))', fontSize: 12, margin: '5px 0 22px' }}>Units sold in the recorded period</p>{top.map((p, i) => { const sold = data.sales.reduce((x, s) => x + s.items.filter((item) => item.productId === p.id).reduce((z, item) => z + item.qty, 0), 0); return <div key={p.id} style={{ marginBottom: 17 }}><div style={{ display: 'flex', justifyContent: 'space-between', fontSize: 12, marginBottom: 7 }}><span style={{ fontWeight: 600 }}>{p.name}</span><span className="mono">{sold} units</span></div><div style={{ height: 7, background: 'hsl(var(--muted))', borderRadius: 10 }}><div style={{ height: '100%', width: `${Math.max(7, sold / Math.max(1, top[0] ? 3 : 1) * 100)}%`, maxWidth: '100%', borderRadius: 10, background: `hsl(var(--chart-${(i % 3) + 1}))` }} /></div></div>})}</section><section className="card" style={{ padding: 20 }}><h2 style={{ margin: 0, fontSize: 15 }}>Payment mix</h2><p style={{ color: 'hsl(var(--muted-foreground))', fontSize: 12, margin: '5px 0 22px' }}>How customers are settling tickets</p>{['Cash', 'Card', 'Credit'].map((m) => { const amount = data.sales.filter((s) => s.paymentMethod === m).reduce((a, s) => a + s.total, 0); return <div key={m} style={{ display: 'flex', alignItems: 'center', gap: 12, marginBottom: 18 }}><div style={{ width: 9, height: 9, borderRadius: 9, background: m === 'Cash' ? 'hsl(var(--chart-1))' : m === 'Card' ? 'hsl(var(--chart-2))' : 'hsl(var(--chart-3))' }} /><span style={{ flex: 1, fontSize: 13 }}>{m}</span><strong>{money(amount)}</strong></div>})}<div style={{ borderTop: '1px solid hsl(var(--border))', paddingTop: 14, display: 'flex', justifyContent: 'space-between', fontSize: 12 }}><span style={{ color: 'hsl(var(--muted-foreground))' }}>Credit outstanding</span><strong style={{ color: 'hsl(var(--primary))' }}>{money(data.customers.reduce((a, c) => a + c.balance, 0))}</strong></div></section></div></main>; }

function SettingsPage({ data, update, reset, notify }: { data: Data; update: (patch: Partial<Data>, message?: string) => void; reset: () => void; notify: (message: string) => void }) { const [form, setForm] = useState(data.settings); useEffect(() => setForm(data.settings), [data.settings]); const set = (key: keyof Settings, value: string | boolean) => setForm((f) => ({ ...f, [key]: value })); return <main className="page"><PageHead eyebrow="Workspace" title="Settings" description="Keep the shop details on every receipt and your data close at hand." /><div className="mobile-grid" style={{ display: 'grid', gridTemplateColumns: '1.15fr .85fr', gap: 16, alignItems: 'start' }}><section className="card" style={{ padding: 22 }}><h2 style={{ fontSize: 16, margin: 0 }}>Shop preferences</h2><p style={{ color: 'hsl(var(--muted-foreground))', fontSize: 12, margin: '5px 0 20px' }}>These details stay on this device and shape your counter workspace.</p><div style={{ display: 'grid', gap: 15 }}><label><span className="field-label">Shop name</span><input className="field" value={form.shopName} onChange={(e) => set('shopName', e.target.value)} data-testid="input-settings-shop-name" /></label><div className="mobile-grid" style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 12 }}><label><span className="field-label">Phone</span><input className="field" value={form.phone} onChange={(e) => set('phone', e.target.value)} data-testid="input-settings-phone" /></label><label><span className="field-label">Currency</span><input className="field" value={form.currency} onChange={(e) => set('currency', e.target.value)} data-testid="input-settings-currency" /></label></div><label><span className="field-label">Address</span><input className="field" value={form.address} onChange={(e) => set('address', e.target.value)} data-testid="input-settings-address" /></label><label><span className="field-label">Receipt footer</span><textarea className="field" rows={3} value={form.receiptFooter} onChange={(e) => set('receiptFooter', e.target.value)} data-testid="input-settings-footer" /></label><label style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', padding: '12px 0', borderTop: '1px solid hsl(var(--border))' }}><span><b style={{ display: 'block', fontSize: 13 }}>Low stock alerts</b><small style={{ color: 'hsl(var(--muted-foreground))' }}>Show warnings on overview and inventory.</small></span><input type="checkbox" checked={form.lowStockAlerts} onChange={(e) => set('lowStockAlerts', e.target.checked)} data-testid="input-settings-low-stock" /></label></div><button className="btn btn-primary" style={{ marginTop: 21 }} onClick={() => update({ settings: form }, 'Settings saved')} data-testid="button-save-settings"><Check size={15} /> Save preferences</button></section><section className="card" style={{ padding: 22 }}><h2 style={{ fontSize: 16, margin: 0 }}>Data controls</h2><p style={{ color: 'hsl(var(--muted-foreground))', fontSize: 12, margin: '5px 0 20px' }}>Hamza Rusk works offline. Your records live in this browser.</p><div style={{ padding: 16, background: 'hsl(var(--accent))', borderRadius: 10, display: 'flex', gap: 12 }}><DatabaseBackup size={20} color="hsl(var(--primary))" /><div><b style={{ fontSize: 13 }}>Local and private</b><p style={{ fontSize: 12, lineHeight: 1.55, margin: '5px 0 0', color: 'hsl(var(--muted-foreground))' }}>No account, network, or server required. Keep this device backed up if the records matter.</p></div></div><button className="btn btn-secondary" style={{ width: '100%', marginTop: 16 }} onClick={() => { exportCSV('hamza-rusk-backup.csv', data.sales.map((s) => ({ receipt: s.receiptNo, customer: s.customerName, total: s.total, payment: s.paymentMethod, date: s.createdAt }))); notify('Sales backup exported'); }} data-testid="button-export-backup"><ArrowDownToLine size={15} /> Export sales backup</button><button className="btn btn-danger" style={{ width: '100%', marginTop: 9 }} onClick={reset} data-testid="button-reset-demo"><RefreshCcw size={15} /> Reset demo data</button></section></div></main>; }

function NotFound() { return <main className="page" style={{ minHeight: '80dvh', display: 'grid', placeItems: 'center' }}><div style={{ textAlign: 'center', maxWidth: 430 }}><div className="serif" style={{ fontSize: 100, lineHeight: .9, color: 'hsl(var(--primary))' }}>404</div><h1 className="serif" style={{ fontSize: 30, margin: '22px 0 8px' }}>That shelf is empty.</h1><p style={{ color: 'hsl(var(--muted-foreground))', fontSize: 13, lineHeight: 1.6 }}>The page you were looking for is not part of this counter workspace.</p><Link href="/" className="btn btn-primary" style={{ marginTop: 18 }} data-testid="link-back-home"><Home size={15} /> Back to overview</Link></div></main>; }

export default App;